import Foundation

/// Optional SwiftPM resource lookup keeps missing/mispackaged host bundles from trapping before verification.
enum ManagedCompilerBundle {
    /// Stable package/target bundle identity generated by this package's Apple SwiftPM configuration.
    private static let name = "FirmingoKit_FirmingoKit.bundle"
    /// SDK class identity locates resources when linked into an app, framework or test host.
    private final class Marker: NSObject {}
    /// Looks only beside the calling app/SDK image; no sibling checkout, environment override or search traversal.
    static func root() -> URL? {
        locate(candidates: [Bundle.main.resourceURL, Bundle(for: Marker.self).resourceURL, Bundle.main.bundleURL].compactMap { $0 })
    }
    /// Injectable finite candidates allow deterministic missing-bundle validation without changing process state.
    static func locate(candidates: [URL]) -> URL? {
        for candidate in candidates {
            if let bundle = Bundle(url: candidate.appendingPathComponent(name)) {
                return bundle.resourceURL?.appendingPathComponent("ManagedCompiler")
            }
        }
        return nil
    }
}
